122	 * so there was no `offset` for the server to honour). It is also the notation this
123	 * project writes a place in, `path/file.ts:42`, so it is one a caller already uses.
124	 *
125	 * A file may hold a colon in its name: `read` tries the literal path first and only
126	 * reads the tail as a range when no such file exists. Hence null, rather than a guess,
127	 * when the tail is not one.
128	 */
129	function rangeInPath(arg: string): { path: string; offset: number; limit?: number } | null {
130	  const at = arg.lastIndexOf(":");
131	  if (at <= 0) return null;
132	  const found = /^([1-9]\d*)(?:-([1-9]\d*))?$/.exec(arg.slice(at + 1));
133	  if (!found) return null;
134	  const from = Number(found[1]);
135	  const to = found[2] === undefined ? undefined : Number(found[2]);
136	  if (to !== undefined && to < from) {
137	    throw new Error(`'${arg}' is not a range: it ends at line ${to}, before line ${from}.`);
138	  }
139	  return { path: arg.slice(0, at), offset: from, limit: to === undefined ? undefined : to - from + 1 };
140	}
